  tian = a.length === 1 ? a[0] + 1 : sum(a);
  ren = a[a.length - 1] + c[0];
  di = c.length === 1 ? c[0] + 1 : sum(c);
  const zong = sum(a) + sum(c);
  wai = tian + di - ren;
