    label = sc >= 2.8 ? "大吉" : sc >= 1.2 ? "吉" : sc >= -0.6 ? "平" : "凶";
  return {
    t,
    r,
    d,
    a,
    b,
    sc,
    label,
    score: label === "大吉" ? 100 : label === "吉" ? 80 : label === "平" ? 55 : 25,
    txt: `${NM_WXN[t]}${NM_WXN[r]}${NM_WXN[d]}:天${a[0] === "相生" ? "生" : a[0] === "比和" ? "比" : a[0] === "相克" ? "克" : a[0] === "被克" ? "受克于" : "泄于"}人,人${b[0] === "相生" ? "生" : b[0] === "比和" ? "比" : b[0] === "相克" ? "克" : b[0] === "被克" ? "受克于" : "泄于"}地`,
  };
