function nmTones(tones) {
  // 读音:相邻不同调、末字平声更朗朗上口
  const t = tones.filter((x) => x > 0);
  if (t.length < 2) return { score: 60, txt: "字数太少,不评读音" };
  let s = 60,
    ev = [];
  let same = 0;
  for (let i = 1; i < t.length; i++) if (t[i] === t[i - 1]) same++;
  s -= same * 14;
  if (same) ev.push("有相邻同调");
  const last = t[t.length - 1];
  if (last === 1 || last === 2) {
    s += 14;
    ev.push("末字平声");
  } else if (last === 3) {
    s -= 6;
  }
  if (new Set(t).size >= 3) {
    s += 12;
    ev.push("声调富于变化");
  }
  if (t.length >= 3 && t.every((x) => x === 4)) {
    s -= 10;
    ev.push("连续仄声");
  }
  return { score: Math.max(10, Math.min(100, s)), txt: ev.join("、") || "中规中矩" };
}
/* 姓名综合评分 */
function nmScore(full, opt) {
  opt = opt || {};
  const sp = nmSplit(full, opt.sLen);
  if (!sp || !sp.giv.length) return null;
  const ov = opt.ov || {},
    S = sp.sur.map((c) => nmChar(c, ov)),
    G = sp.giv.map((c) => nmChar(c, ov)),
    all = S.concat(G);
  const unk = all.filter((x) => x.k === null);
  if (unk.length) return { sp, S, G, unk: unk.map((x) => x.c), incomplete: true };
  const w = nmWuge(
      S.map((x) => x.k),
      G.map((x) => x.k),
    ),
    sc = nmSancai(w),
    tn = nmTones(all.map((x) => x.tone));
  // 五行分布:五格五行(人格×2,地格×1.5,总格×1,天外×.5)+ 字形五行
  const vec = [0, 0, 0, 0, 0];
  vec[w.ren.wx] += 2;
  vec[w.di.wx] += 1.5;
  vec[w.zong.wx] += 1;
  vec[w.tian.wx] += 0.5;
  vec[w.wai.wx] += 0.5;
  all.forEach((x) => {
    if (x.wx >= 0) vec[x.wx] += 1;
  });
  const tot = vec.reduce((a, b) => a + b, 0),
    share = vec.map((v) => v / tot);
  let bazi = null;
  if (opt.favor) {
    let v = 0;
    for (let e = 0; e < 5; e++) {
      if (opt.favor.includes(e)) v += share[e];
      else if ((opt.avoid || []).includes(e)) v -= share[e];
    }
    bazi = { v, score: Math.round(50 + 50 * Math.max(-1, Math.min(1, v * 1.6))) };
  }
  const parts = [
    { k: "人格(主运)", s: w.ren.sl.s, w: 22, t: `${w.ren.n} ${w.ren.sl.t}` },
    { k: "总格", s: w.zong.sl.s, w: 18, t: `${w.zong.n} ${w.zong.sl.t}` },
    { k: "地格", s: w.di.sl.s, w: 12, t: `${w.di.n} ${w.di.sl.t}` },
    { k: "外格", s: w.wai.sl.s, w: 8, t: `${w.wai.n} ${w.wai.sl.t}` },
    { k: "天格", s: w.tian.sl.s, w: 5, t: `${w.tian.n} ${w.tian.sl.t}` },
    { k: "三才", s: sc.score, w: 15, t: `${sc.txt}(${sc.label})` },
    { k: "读音", s: tn.score, w: 5, t: tn.txt },
  ];
  if (bazi)
    parts.push({
      k: "八字喜用匹配",
      s: bazi.score,
      w: 20,
      t: `名字五行与喜用的契合 ${bazi.score}`,
    });
  const W = parts.reduce((a, p) => a + p.w, 0),
    total = Math.round(parts.reduce((a, p) => a + p.s * p.w, 0) / W);
  const rating = total >= 85 ? "上佳" : total >= 72 ? "良好" : total >= 58 ? "中等" : "欠佳";
  return { sp, S, G, w, sc, tn, share, vec, bazi, parts, total, rating, all };
}
