function nmShopScore(name, opt) {
  opt = opt || {};
  const cs = [...name].map((c) => nmChar(c, opt.ov || {}));
  if (cs.length < 2) return null;
  if (cs.some((x) => x.k === null))
    return { incomplete: true, unk: cs.filter((x) => x.k === null).map((x) => x.c), cs };
  const total = cs.reduce((a, x) => a + x.k, 0),
    sl = nmShuli(total),
    tn = nmTones(cs.map((x) => x.tone));
  const vec = [0, 0, 0, 0, 0];
  cs.forEach((x) => {
    if (x.wx >= 0) vec[x.wx] += 1;
  });
  vec[numWx(total)] += 0.6;
  if (opt.extra) vec[opt.extra.wx] += opt.extra.w;
  const tot = vec.reduce((a, b) => a + b, 0),
    share = vec.map((v) => v / tot);
  const parts = [
    { k: "总格数理", s: sl.s, w: 28, t: `${total} ${sl.t}` },
    { k: "读音", s: tn.score, w: 14, t: tn.txt },
  ];
  const ind = opt.ind && NM_IND[opt.ind];
  if (ind) {
    let a = 0;
    ind.wx.forEach((e, i) => {
      a += share[e] * (i === 0 ? 1 : 0.6);
    });
    const gen = (ind.wx[0] + 4) % 5;
    a += share[gen] * 0.4;
    const s = Math.round(Math.min(100, 35 + a * 110));
    parts.push({
      k: "行业五行契合",
      s,
      w: 22,
      t: `${ind.wx.map((e) => NM_WXN[e]).join("、")}(${ind.note})`,
    });
  }
  if (opt.favor) {
    let v = 0;
    for (let e = 0; e < 5; e++) {
      if (opt.favor.includes(e)) v += share[e];
      else if ((opt.avoid || []).includes(e)) v -= share[e];
    }
    parts.push({
      k: "店主喜用契合",
      s: Math.round(50 + 50 * Math.max(-1, Math.min(1, v * 1.6))),
      w: 26,
      t: "名字五行与店主喜用的契合",
    });
  }
  const good = cs.filter((x) => NM_POOLWX[x.c] !== undefined).length / cs.length;
  parts.push({
    k: "字义美好度",
    s: Math.round(40 + good * 60),
    w: 10,
    t: `吉祥常用字占 ${Math.round(good * 100)}%`,
  });
  const W = parts.reduce((a, p) => a + p.w, 0),
    score = Math.round(parts.reduce((a, p) => a + p.s * p.w, 0) / W);
  return {
    cs,
    total,
    sl,
    tn,
    share,
    parts,
    score,
    rating: score >= 85 ? "上佳" : score >= 72 ? "良好" : score >= 58 ? "中等" : "欠佳",
  };
}
function nmShopGen(opt) {
  const ind = NM_IND[opt.ind];
  if (!ind) return [];
  const fav = opt.favor && opt.favor.length ? opt.favor : ind.wx;
  const wxSet = [...new Set([...fav.slice(0, 3), ...ind.wx])];
  const sufs = opt.suffix ? [opt.suffix] : ind.suf,
    seen = new Set(),
    out = [];
  const consider = (nm, e, key) => {
    if (seen.has(nm)) return;
    seen.add(nm);
    if (opt.must && !nm.includes(opt.must)) return;
    const r = nmShopScore(nm, {
      ind: opt.ind,
      favor: opt.favor,
      avoid: opt.avoid,
      extra: { wx: e, w: 2 },
    });
    if (r && !r.incomplete) out.push({ name: nm, key, r });
  };
  wxSet.forEach((e) => NM_WORDS[e].forEach((w) => sufs.forEach((s) => consider(w + s, e, w))));
  if (opt.must) {
    wxSet.forEach((e) => {
      [...NM_POOL[NM_WXN[e]]].forEach((c) => {
        if (c === opt.must) return;
        sufs.forEach((s) => {
          consider(opt.must + c + s, e, opt.must + c);
          consider(c + opt.must + s, e, c + opt.must);
        });
      });
    });
  }
  out.sort((a, b) => b.r.score - a.r.score || a.name.localeCompare(b.name));
  const res = [],
    cnt = {},
    cnt1 = {};
  for (const x of out) {
    const f = x.name[0];
    if ((cnt[x.key] || 0) >= 2 || (cnt1[f] || 0) >= 3) continue;
    cnt[x.key] = (cnt[x.key] || 0) + 1;
    cnt1[f] = (cnt1[f] || 0) + 1;
    res.push(x);
    if (res.length >= (opt.n || 16)) break;
  }
  return res;
}

