function fateTaisui(P, year) {
  const yb = (((year - 4) % 12) + 12) % 12,
    mb = P.bz.pill[0].b,
    rels = pplZhiRel(mb, yb),
    out = [];
  rels.forEach((r) => {
    const k =
      r.t === "同支"
        ? "值"
        : r.t === "冲"
          ? "冲"
          : r.t === "刑" || r.t === "自刑"
            ? "刑"
            : r.t === "害"
              ? "害"
              : r.t === "破"
                ? "破"
                : r.t === "六合"
                  ? "合"
                  : r.t === "半合"
                    ? "半合"
                    : null;
    if (k)
      out.push({ k, name: FATE_TSY[k][0], txt: FATE_TSY[k][1], v: FATE_TSY[k][2], raw: r.txt });
  });
  return { yb, items: out, v: out.reduce((a, x) => a + x.v, 0) };
}
function fateSs(P, stem) {
  return shishen(P.bz.dm, stem);
}
function fateTone(P, scn, idx) {
  const S = FATE_SCN[scn];
  if (S.grave) return { v: 0, notes: [] };
  const s = idx % 10,
    b = idx % 12,
    ssS = fateSs(P, s),
    ssB = fateSs(P, CANG[b][0]),
    male = P.gender === "1" || P.gender === "M";
  let good = S.good,
    bad = S.bad;
  if (good === "spouse") {
    good = male ? ["正财", "偏财"] : ["正官", "七杀"];
    bad = male ? ["劫财", "比肩"] : ["伤官"];
  }
  let v = 0;
  const notes = [];
  [
    [ssS, 0.6],
    [ssB, 0.4],
  ].forEach(([x, w]) => {
    if (good.includes(x)) {
      v += w * 1.2;
      notes.push(`${x}${w > 0.5 ? "透干" : "藏支"}(利)`);
    } else if (bad.includes(x)) {
      v -= w * 1.0;
      notes.push(`${x}${w > 0.5 ? "透干" : "藏支"}(扰)`);
    }
  });
  const dB = P.bz.pill[2].b,
    mB = P.bz.pill[1].b,
    tz = S.zi === "月" ? mB : dB;
  const rel = pplZhiRel(tz, b);
  rel.forEach((r) => {
    if (r.t === "六合" || r.t === "半合") {
      v += 0.35;
      notes.push(`合${S.zhi}支`);
    } else if (r.t === "冲") {
      v -= S.horse ? 0.2 : 0.55;
      notes.push(`冲${S.zhi}支(变动)`);
    } else if (r.t === "害" || r.t === "刑") {
      v -= 0.25;
      notes.push(`${r.t}${S.zhi}支`);
    }
  });
  if (S.horse && [2, 5, 8, 11].includes(b)) {
    v += 0.25;
    notes.push("驿马动(利行)");
  }
  return { v, notes };
}
const fatePct = (x) => Math.max(8, Math.min(96, Math.round(50 + 21 * x)));
const fateLabel = (p) =>
  p >= 75 ? "顺" : p >= 60 ? "偏顺" : p >= 45 ? "平" : p >= 32 ? "偏阻" : "多阻";
function fateYear(P, scn, year) {
  const idx = (((year - 4) % 60) + 60) % 60,
    b = scoreGZ(P.bz, P.deep, idx, 0.6, 0.4),
    t = fateTone(P, scn, idx),
    ts = fateTaisui(P, year);
  const S = FATE_SCN[scn],
    v = S.grave ? 0 : b.sc * 0.6 + t.v + ts.v * 0.5,
    p = S.grave ? null : fatePct(v);
  return {
    y: year,
    gz: gz(idx),
    ss: fateSs(P, idx % 10),
    base: b,
    tone: t,
    ts,
    v,
    p,
    label: p === null ? "" : fateLabel(p),
    notes: [...b.notes, ...t.notes],
  };
}
function fateMonths(P, scn, year) {
  const S = FATE_SCN[scn],
    lm = liuyue(P.bz, P.deep, year);
  return lm.map((m) => {
    const idx = ganzhiIdxOf(m.gz),
      t = fateTone(P, scn, idx),
      v = S.grave ? 0 : m.sc * 0.6 + t.v;
    return {
      name: m.name,
      gz: m.gz,
      from: m.from,
      v,
      p: S.grave ? null : fatePct(v),
      notes: [...m.notes, ...t.notes],
    };
  });
}
const ganzhiIdxOf = (s) => {
  for (let i = 0; i < 60; i++) if (gz(i) === s) return i;
  return 0;
};
/* 日期:基础择日分 + 个人增强;people 为需要核对冲煞的人(含命主) */
function fateDayAdj(P, info) {
  let adj = 0;
  const why = [];
  const xy = P.deep.xy,
    ds = info.dayIdx % 10,
    db = info.dayIdx % 12;
  const f = (x) => (xy.favor.includes(x) ? 1 : xy.avoid.includes(x) ? -1 : 0);
  const a = f(GAN_WX[ds]) * 0.5 + f(GAN_WX[CANG[db][0]]) * 0.4;
  if (a) {
    adj += a;
    why.push(a > 0 ? "日干支五行合喜用" : "日干支五行犯忌神");
  }
  const dz = P.bz.pill[2].b,
    rels = pplZhiRel(dz, db);
  rels.forEach((r) => {
    if (r.t === "冲") {
      adj -= 1.5;
      why.push("冲日支");
    } else if (r.t === "六合") {
      adj += 1;
      why.push("合日支");
    } else if (r.t === "半合") {
      adj += 0.5;
      why.push("半合日支");
    } else if (r.t === "害" || r.t === "刑") {
      adj -= 0.7;
      why.push(r.t + "日支");
    }
  });
  if (info.dayIdx === P.bz.dayIdx) {
    adj -= 0.8;
    why.push("伏吟本命日柱");
  }
  return { adj, why };
}
function fateDates(P, scn, startY, startM, startD, days, people) {
  const S = FATE_SCN[scn],
    birthZ = P.bz.pill[0].b,
    arr = zeriRange(startY, startM, startD, days, S.ev, birthZ),
    out = [];
  arr.forEach((x) => {
    const a = fateDayAdj(P, x.info),
      sc = x.sc + a.adj,
      conflicts = [];
    (people || []).forEach((q) => {
      const yz = q.bz.pill[0].b,
        dz = q.bz.pill[2].b;
      if (x.info.chongZ === yz) conflicts.push({ who: q.name, t: `冲属${ZODIAC[yz]}` });
      else if (x.info.chongZ === dz) conflicts.push({ who: q.name, t: "冲日支" });
    });
    out.push({
      info: x.info,
      sc,
      base: x.sc,
      why: x.why.concat(a.why),
      flags: x.flags,
      conflicts,
      tier: zrTierOf(x, S.ev, birthZ),
    });
  });
  return out;
}
function fatePick(dates, n, needClean) {
  return dates
    .filter(
      (d) => !d.flags.ji && !d.flags.chong && !d.flags.po && (!needClean || !d.conflicts.length),
    )
    .sort((a, b) => b.sc - a.sc)
    .slice(0, n);
}
function fateDirs(P, scn) {
  const S = FATE_SCN[scn],
    bh = bazhaiOf({ bz: P.bz, opt: { gender: P.gender === "1" || P.gender === "M" ? "M" : "F" } }),
    good = bh.dirs.filter((d) => ["生气", "天医", "延年"].includes(d.n)),
    bad = bh.dirs.filter((d) => ["绝命", "五鬼", "祸害", "六煞"].includes(d.n));
  const fav = P.deep.xy.favor;
  return {
    mg: bh.mg,
    good,
    bad,
    favWx: fav.map((e) => ({ wx: e, dir: FATE_WXDIR[e], color: FATE_COLOR[e] })),
    kind: S.dirKind,
  };
}
function fateReport(P, scn, year, today, people) {
  const y = fateYear(P, scn, year),
    months = fateMonths(P, scn, year),
    dates = fateDates(P, scn, today.y, today.m, today.d, 90, people);
  return {
    scn,
    S: FATE_SCN[scn],
    year: y,
    next: fateYear(P, scn, year + 1),
    months,
    dates,
    pick: fatePick(dates, 6, false),
    clean: fatePick(dates, 6, true),
    dirs: fateDirs(P, scn),
    caution: FATE_CAUTION[scn],
  };
}

