const GEO_SHORT = (n) => n.replace(/(维吾尔|壮族|回族)?自治区$|特别行政区$|省$|市$/, "");
function geoCities(pi) {
  return (GEO_DATA[pi] || [null, []])[1];
}
function geoAreas(pi, ci) {
  const c = geoCities(pi)[ci];
  return c ? c[3] : [];
}
function geoFind(lon, lat) {
  // 按坐标反查(容差 0.06°),返回 [省,市,区] 下标
  let best = null;
  GEO_DATA.forEach((p, pi) =>
    p[1].forEach((c, ci) => {
      const d = Math.hypot(c[1] - lon, c[2] - lat);
      if (d < 0.06 && (!best || d < best.d)) best = { d, pi, ci, ai: -1 };
      c[3].forEach((a, ai) => {
        const e = Math.hypot(a[1] - lon, a[2] - lat);
        if (e < 0.06 && (!best || e < best.d)) best = { d: e, pi, ci, ai };
      });
    }),
  );
  return best;
}

(function () {
  const fix = [["福建省", "漳州市", "龙海区", 117.82, 24.45]];
  fix.forEach(([p, c, a, lo, la]) => {
    const P = GEO_DATA.find((x) => x[0] === p);
    if (!P) return;
    const C = P[1].find((x) => x[0] === c);
    if (!C) return;
    const A = C[3].find((x) => x[0] === a);
    if (A) {
      A[1] = lo;
      A[2] = la;
    }
  });
})();

