function hhPct(kind, score) {
  const t = HH_Q[kind] || HH_Q.friend;
  if (score <= t[0]) return 1;
  if (score >= t[20]) return 99;
  for (let i = 1; i <= 20; i++) {
    if (score <= t[i]) {
      const lo = t[i - 1],
        hi = t[i],
        f = hi > lo ? (score - lo) / (hi - lo) : 0.5;
      return Math.max(1, Math.min(99, Math.round((i - 1 + f) * 5)));
    }
  }
  return 99;
}
