function cgLiang(q) {
  const l = Math.floor(q / 10),
    m = q % 10;
  return (l ? l + "两" : "") + (m ? m + "钱" : "");
}
/* 农历生辰 → 骨重。ly 农历年(春节为界的农历年数),lm 农历月(1-12,闰月按本月),ld 农历日,hb 时辰地支序(子=0) */
function cgCalc(ly, lm, ld, hb) {
  const yi = (((ly - 4) % 60) + 60) % 60,
    y = CG_YEAR[yi],
    m = CG_MONTH[lm - 1],
    d = CG_DAY[ld - 1],
    h = CG_HOUR[hb],
    tot = y + m + d + h,
    song = CG_SONG[Math.max(0, Math.min(50, tot - 21))];
  return { yi, y, m, d, h, tot, song, low: tot < 21 || tot > 71 };
}

