const NE_MAP = (() => {
  const m = {};
  for (const [k, v] of Object.entries(NE_ST))
    v.pairs.forEach(([a, b]) => {
      m["" + a + b] = k;
      m["" + b + a] = k;
    });
  return m;
})();
const NE_W = { 天医: 2, 延年: 2, 生气: 2, 伏位: 0.3, 绝命: -2, 祸害: -1.5, 五鬼: -1, 六煞: -1.5 };
function neAnalyze(str, kind) {
  let digits = String(str || "").replace(/\D/g, ""),
    note = "";
  if (kind === "phone") {
    if (digits.length >= 11) {
      digits = digits.slice(-8);
      note = "手机号取后 8 位分析(前 3 位是运营商号段)。";
    } else if (digits.length > 8) {
      digits = digits.slice(-8);
      note = "取后 8 位分析。";
    }
  }
  if (digits.length < 2) return { err: "请至少输入两位数字。" };
  if (digits.length > 24) ((digits = digits.slice(0, 24)), (note += "数字过长,只取前 24 位。"));
  const eff = [];
  [...digits].forEach((c, i) => {
    const d = +c;
    if (d !== 0 && d !== 5) eff.push({ d, i });
  });
  const pairs = [];
  for (let k = 0; k < eff.length - 1; k++) {
    const a = eff[k],
      b = eff[k + 1],
      mid = digits.slice(a.i + 1, b.i),
      star = NE_MAP["" + a.d + b.d];
    pairs.push({
      a: a.d,
      b: b.d,
      from: a.i,
      to: b.i,
      star,
      amp: mid.includes("5"),
      zero: mid.includes("0"),
      last: b.i >= digits.length - 4,
    });
  }
  const cnt = {};
  Object.keys(NE_ST).forEach((k) => (cnt[k] = 0));
  pairs.forEach((p) => cnt[p.star]++);
  let sc = 0,
    wsum = 0;
  pairs.forEach((p) => {
    const w = 1 + (p.last ? 0.5 : 0) + (p.amp ? 0.3 : 0);
    sc += NE_W[p.star] * w;
    wsum += w;
  });
  const idx = wsum ? sc / wsum : 0,
    lv = !pairs.length
      ? "无可组合"
      : idx >= 1
        ? "偏吉"
        : idx >= 0.3
          ? "略吉"
          : idx > -0.3
            ? "平"
            : idx > -1
              ? "略凶"
              : "偏凶";
  const specials = [...digits].map((c, i) => ({ c, i })).filter((x) => x.c === "0" || x.c === "5");
  const last4 = pairs.filter((p) => p.last).map((p) => p.star);
  const top = Object.entries(cnt)
    .filter(([, v]) => v > 0)
    .sort((a, b) => b[1] - a[1]);
  return {
    digits,
    note,
    pairs,
    cnt,
    idx: Math.round(idx * 100) / 100,
    lv,
    specials,
    last4,
    top,
    n0: (digits.match(/0/g) || []).length,
    n5: (digits.match(/5/g) || []).length,
  };
}
