/* 本命星:男 11−数根;女 数根+4(>9 减 9)。yearNum 为立春为界的年份 */
function ksBenming(yearNum, male) {
  const dr = ksDr(yearNum);
  let v = male ? 11 - dr : dr + 4;
  while (v > 9) v -= 9;
  while (v < 1) v += 9;
  return v;
}
