/* ---------------- 梅花多法起卦 ---------------- */
function mhCast(mode, v, hb) {
  const t8 = (n) => ((n % 8) + 8) % 8 || 8,
    t6 = (n) => ((n % 6) + 6) % 6 || 6;
  let up, lo, mv, how;
  const h = hb + 1;
  if (mode === "two") {
    const [a, b] = v;
    up = t8(a);
    lo = t8(b);
    mv = t6(a + b + h);
    how = `上卦 ${a} 除 8 余 ${up};下卦 ${b} 除 8 余 ${lo};动爻 (${a}+${b}+时辰数${h}) 除 6 余 ${mv}`;
  } else if (mode === "three") {
    const [a, b, c] = v;
    up = t8(a);
    lo = t8(b);
    mv = t6(c);
    how = `上卦 ${a}→${up};下卦 ${b}→${lo};动爻 ${c} 除 6 余 ${mv}`;
  } else if (mode === "one") {
    const n = v[0];
    up = t8(n);
    lo = t8(n + h);
    mv = t6(n + h);
    how = `上卦 ${n} 除 8 余 ${up};下卦 (${n}+时辰数${h}) 除 8 余 ${lo};动爻 (${n}+${h}) 除 6 余 ${mv}`;
  } else if (mode === "digits") {
    const s = String(v[0]).replace(/\D/g, "");
    const k = Math.ceil(s.length / 2),
      a = [...s.slice(0, k)].reduce((x, y) => x + +y, 0),
      b = [...s.slice(k)].reduce((x, y) => x + +y, 0) || a;
    up = t8(a);
    lo = t8(b);
    mv = t6(a + b + h);
    how = `数字 ${s} 前半和 ${a}→上卦 ${up};后半和 ${b}→下卦 ${lo};动爻 (${a}+${b}+时辰数${h}) 除 6 余 ${mv}`;
  }
  const lines = hexFromTri(up, lo),
    ben = hexInfo(lines),
    hu = hexInfo([lines[1], lines[2], lines[3], lines[2], lines[3], lines[4]]);
  const bl = lines.slice();
  bl[mv - 1] = 1 - bl[mv - 1];
  const bian = hexInfo(bl),
    lower = mv <= 3,
    ti = lower ? up : lo,
    yong = lower ? lo : up;
  return { up, lo, mv, ben, hu, bian, ti, yong, how, tiyong: tiyong(ti, yong) };
}

