function zfMonths(zw, lunar, hb, year) {
  const yb = (((year - 4) % 12) + 12) % 12,
    dj = zfDouJun(zw, yb, lunar.month, hb),
    out = [];
  for (let k = 1; k <= 12; k++) {
    const b = (dj + k - 1) % 12,
      p = zfPalAt(zw, b);
    out.push({ k, name: ZF_MON[k - 1] + "月", b, pal: p, stem: p.stem, sh: zfSihuaOf(zw, p.stem) });
  }
  return { yb, dj, list: out };
}
function zfDays(zw, monthB, days) {
  const out = [];
  for (let d = 1; d <= days; d++) {
    const b = (monthB + d - 1) % 12,
      p = zfPalAt(zw, b);
    out.push({ d, b, pal: p, stem: p.stem });
  }
  return out;
}
function bzDayFlow(bz, deep, y, m, d) {
  const di = dayInfo(y, m, d),
    idx = di.dayIdx,
    r = scoreGZ(bz, deep, idx, 0.6, 0.4);
  return {
    y,
    m,
    d,
    idx,
    gz: gz(idx),
    ss: shishen(bz.dm, idx % 10),
    sc: r.sc,
    lv: LV(r.sc),
    notes: r.notes,
    info: di,
  };
}
function bzHourFlow(bz, deep, dayIdx) {
  const ds = dayIdx % 10,
    out = [];
  for (let b = 0; b < 12; b++) {
    const s = ((ds % 5) * 2 + b) % 10,
      idx = ganzhiIdx(s, b),
      r = scoreGZ(bz, deep, idx, 0.6, 0.4);
    out.push({
      b,
      gz: gz(idx),
      ss: shishen(bz.dm, s),
      sc: r.sc,
      lv: LV(r.sc),
      notes: r.notes,
      span: `${f2((b * 2 + 23) % 24)}:00–${f2((b * 2 + 1) % 24)}:00`,
    });
  }
  return out;
}

